9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field, reporting every
13	 * offending field at once. Runs first and binds the body <em>without</em> {@code @Valid} so this rule
14	 * decides the 400 response shape rather than bean validation. A valid body is republished for
15	 * {@link BuildOwner} to consume.
16	 */
17	public class ValidateOwnerFields {
18	
19	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
20	            throws MissingRequiredFieldsException {
21	        List<String> missing = new ArrayList<>();
22	        requirePresent(missing, "firstName", request.getFirstName());
23	        requirePresent(missing, "lastName", request.getLastName());
24	        requirePresent(missing, "address", request.getAddress());
25	        requirePresent(missing, "city", request.getCity());
26	        requirePresent(missing, "telephone", request.getTelephone());
27	        if (!missing.isEmpty()) {
28	            throw new MissingRequiredFieldsException(missing);
29	        }
30	        validated.set(request);
31	    }
32	
33	    private static void requirePresent(List<String> missing, String field, String value) {
34	        if (value == null || value.isBlank()) {
35	            missing.add(field);
36	        }
37	    }
38	}
