9	/**
10	 * Rejects a create request that would place the new owner in a household already occupied by an
11	 * existing owner — same last name and address, compared case-insensitively with whitespace collapsed
12	 * (see {@link HouseholdNormalizer}). A collision is a 409 via {@link DuplicateHouseholdException},
13	 * unless the request sets {@code sharesHousehold} true to acknowledge the shared household.
14	 */
15	public class EnsureUniqueHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return;
21	        }
22	        String key = HouseholdNormalizer.key(request.getLastName(), request.getAddress());
23	        for (Owner owner : ownerRepository.findAll()) {
24	            if (key.equals(HouseholdNormalizer.key(owner.getLastName(), owner.getAddress()))) {
25	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
26	            }
27	        }
28	    }
29	}
