7	/**
8	 * Assigns the owner's customerCode, formatted {@code <LAST3>-<NNNN>} where LAST3 is the upper-cased
9	 * first three letters of the last name and NNNN is a global 4-digit zero-padded sequence equal to
10	 * one more than the current number of owners (e.g. {@code SMI-0007}). Runs before {@link SaveOwner},
11	 * so the count excludes the owner currently being created. Mutates the built {@link Owner} in place.
12	 */
13	public class AssignCustomerCode {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String lastName = owner.getLastName();
17	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
18	        int sequence = ownerRepository.findAll().size() + 1;
19	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
20	    }
21	}
