3	/**
4	 * Canonical household comparison shared by the create pipeline: {@link EnsureUniqueHousehold} uses it
5	 * to decide whether two owners share a household. A household is identified by last name plus address,
6	 * each compared case-insensitively with runs of whitespace collapsed to a single space and outer
7	 * whitespace trimmed. Not a pipeline step, so it is free to expose plain helpers.
8	 */
9	public final class HouseholdNormalizer {
10	
11	    private HouseholdNormalizer() {
12	    }
13	
14	    /**
15	     * Builds the canonical household key for an owner from its last name and address. Two owners
16	     * belong to the same household when their keys are equal. Either field may be {@code null}, which
17	     * normalizes to an empty token.
18	     */
19	    public static String key(String lastName, String address) {
20	        // '\n' separates the fields so that a boundary shift (e.g. "ab"+"c" vs "a"+"bc") cannot forge a
21	        // collision; it never appears in a normalized value.
22	        return normalize(lastName) + "\n" + normalize(address);
23	    }
24	
25	    /** Lower-cases and collapses whitespace to single spaces, trimming the ends; {@code null} → "". */
26	    private static String normalize(String value) {
27	        if (value == null) {
28	            return "";
29	        }
30	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
31	    }
32	}
